head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldstf75500";
scwin.editor = undefined;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_ctxDefaults
 * @description 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다. 진입 기본값 충전 — 파라미터로 안 온 키에 스펙 기본값(조건 평가보다 먼저).
 * @returns {void}
 * @hidden N
 */
scwin.init_ctxDefaults = function () {
    const cds = {"authYn":"Y"};
    const pc0 = $c.util.getComponent("dma_pageContext");
    if (!pc0 || !pc0.get || !pc0.set) { return; }
    for (let ck in cds) { const cv0 = pc0.get(ck); if (cv0 === undefined || cv0 === null || cv0 === '') { pc0.set(ck, cds[ck]); } }
};

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — pageContext.ssMarket, pageContext.psDepCd, usrLdMktTpCd, pageContext.usrTpCd

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_ssMarket", fn: function(){ return ((dma_pageContext.get("ssMarket") ?? "") === '1' && (dma_pageContext.get("psDepCd") ?? "") === '2610'); } }, { id: "if_ssMarket_2", fn: function(){ return ((dma_pageContext.get("ssMarket") ?? "") === '2' && (dma_pageContext.get("psDepCd") ?? "") === '3410'); } }, { id: "if_ssMarket_3", fn: function(){ return ((dma_pageContext.get("ssMarket") ?? "") !== '1' && (dma_pageContext.get("ssMarket") ?? "") !== '2'); } }, { id: "if_usrLdMktTpCd", fn: function(){ return ((dma_pageContext.get("usrLdMktTpCd") ?? "") === '1'); } }, { id: "if_usrLdMktTpCd_2", fn: function(){ return ((dma_pageContext.get("usrLdMktTpCd") ?? "") === '2'); } }, { id: "if_usrLdMktTpCd_3", fn: function(){ return ((dma_pageContext.get("usrLdMktTpCd") ?? "") === '6'); } }, { id: "if_usrLdMktTpCd", fn: function(){ return ((dma_pageContext.get("usrTpCd") ?? "") !== '1'); } }, { id: "if_usrLdMktTpCd_2", fn: function(){ return ((dma_pageContext.get("usrTpCd") ?? "") !== '1'); } }, { id: "if_usrLdMktTpCd_3", fn: function(){ return ((dma_pageContext.get("usrTpCd") ?? "") !== '1'); } }, { id: "if_usrTpCd_2", fn: function(){ return ((dma_pageContext.get("usrTpCd") ?? "") === '1'); } }, { id: "if_authYn", fn: function(){ return (((dma_pageContext.get("ssMarket") ?? "") === '1' && (dma_pageContext.get("psDepCd") ?? "") === '2610') || ((dma_pageContext.get("ssMarket") ?? "") === '2' && (dma_pageContext.get("psDepCd") ?? "") === '3410') || ((dma_pageContext.get("ssMarket") ?? "") !== '1' && (dma_pageContext.get("ssMarket") ?? "") !== '2')); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "ipt_formatKeywrd", fn: function () { return String(String((dma_pageContext.get("formatKeywrd") ?? ""))); } },
        { childId: "ipt_integSrchNo", fn: function () { return String(String((dma_pageContext.get("integSrchNo") ?? ""))); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        await scwin.tx_fn_searchList();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf75500.onpageload' }); }
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: self_action). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_load_list();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.editor =new Dext5editor("dext5editor1"); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf75500' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_ctxDefaults();
        scwin.init_rowCopy();
        scwin.init_conds();
        await scwin.init_loadList();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldstf75500.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name headerKeywrdForm_onsubmit
 * @description headerKeywrdForm onsubmit 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.headerKeywrdForm_onsubmit = function(e){
    try {
        return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf75500.headerKeywrdForm_onsubmit' }); }
};

/**
 * @method
 * @name ipt_formatKeywrd_onkeydown
 * @description ipt_formatKeywrd 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_formatKeywrd_onkeydown = async function(e){
    try {
        const ev = e;
        const event = ev;
        if(event.keyCode===13){$c.util.getComponent("dma_loadListReq").set("pageIndex", 1);await scwin.tx_fn_searchList()}

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf75500.ipt_formatKeywrd_onkeydown' }); }
};

/**
 * @method
 * @name input_24_onclick
 * @description 「조회」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.input_24_onclick = function(e){
    try {
        openKeywrdList()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf75500.input_24_onclick' }); }
};

/**
 * @method
 * @name input_26_onclick
 * @description 「조회」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.input_26_onclick = async function(e){
    try {
        $c.util.getComponent("dma_loadListReq").set("pageIndex", 1);await scwin.tx_fn_searchList();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf75500.input_26_onclick' }); }
};

/**
 * @method
 * @name btn_regExpls_onclick
 * @description 「저장」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_regExpls_onclick = async function(e){
    try {
        await scwin.regExpls()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf75500.btn_regExpls_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_searchList
 * @description search List 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_searchList = async function () {
    const sbmOptions = {
        id: "tx_fn_searchList",
        method: "post",
        action: "/ods/integsrch.do",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_searchTaskExp
 * @description search Task Exp 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_searchTaskExp = async function () {
    const sbmOptions = {
        id: "tx_fn_searchTaskExp",
        method: "post",
        action: "/ods/integsrch.do",
        ref: "dma_searchTaskExpReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_regExpls
 * @description reg Expls 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_regExpls = async function () {
    const sbmOptions = {
        id: "tx_fn_regExpls",
        method: "post",
        action: "/ods/integsrch.do",
        ref: "dma_regExplsReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_load_list
 * @description load list 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_load_list = async function () {
    const sbmOptions = {
        id: "tx_load_list",
        method: "post",
        action: "/ods/integsrch.do",
        ref: "dma_loadListReq",
        target: "dlt_chrgInstIsList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setEditor
 * @description set Editor 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.setEditor = function (data) {
    if (data.mktact.mktact_rsn_contn) {
        try {
            DEXT5.setBodyValue(data.mktact.mktact_rsn_contn, "dext5editor1");
        } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'jldstf75500' }); }
        DEXT5.setEditorChangeMode("source", "dext5editor1");
        DEXT5.setEditorChangeMode("design", "dext5editor1");
    } else {
        DEXT5.setBodyValue("", "dext5editor1");
    }
    DEXT5.setDirty("dext5editor1");
};

/**
 * @method
 * @name setKeywrd
 * @description set Keywrd 처리
 * @param {*} keywrd keywrd
 * @returns {void}
 * @hidden N
 */
scwin.setKeywrd = function (keywrd) {
    $c.util.getComponent('ipt_formatKeywrd').setValue(keywrd);
};

// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)

/**
 * @method
 * @name searchTaskExpDone
 * @description search Task Exp Done 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.searchTaskExpDone = function (data) {
    $c.util.getComponent('editorArea').setStyle('display', 'block');
    scwin.setEditor(data);
};

/**
 * @method
 * @name searchTaskExp
 * @description search Task Exp 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchTaskExp = async function () {
    const r = await scwin.tx_fn_searchTaskExp();
    try {
        scwin.searchTaskExpDone.call(window, JSON.stringify((r && r.responseJSON && (r.responseJSON.body != null ? r.responseJSON.body : r.responseJSON)) || {}));
    }
    catch (_se) {
        await $c.exception.handleError(_se, { notify: 'none', context: 'jldstf75500.fn_searchTaskExp' });
    }
    return r;
};

/**
 * @method
 * @name regExplsDone
 * @description reg Expls Done 처리
 * @param {*} data 데이터
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.regExplsDone = async function (data) {
    scwin.setEditor(data);
    await $c.win.alert("저장되었습니다.");
};

/**
 * @method
 * @name regExpls
 * @description reg Expls 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.regExpls = async function () {
    const r = await scwin.tx_fn_regExpls();
    try {
        scwin.regExplsDone.call(window, JSON.stringify((r && r.responseJSON && (r.responseJSON.body != null ? r.responseJSON.body : r.responseJSON)) || {}));
    }
    catch (_se) {
        await $c.exception.handleError(_se, { notify: 'none', context: 'jldstf75500.fn_regExpls' });
    }
    return r;
};
